mapper.sql:
WHERE f.IS_DELETE = 0
  AND f.FACTORY_CODE = #{factoryCode}
  AND f.YEAR = #{year}
  AND f.MONTH = #{month}

  AND EXISTS (
      SELECT 1 FROM T_MP_PROC_VERSION v
      WHERE v.PRODUCTION_VERSION = f.PRODUCTION_VERSION
        AND v.IS_DELETE = 0
        AND v.IS_FINAL = '1'
        AND v.FACTORY_CODE = f.FACTORY_CODE
        AND v.YEAR = f.YEAR
        AND v.MONTH = f.MONTH
  )

    AND f.MATERIAL_CODE LIKE CONCAT('%', #{materialCode}, '%')


    AND f.MATERIAL_DESC LIKE CONCAT('%', #{materialDesc}, '%')


    AND f.PRODUCT_STATUS = #{productStatus}


    AND f.PRODUCT_TYPE_CODE = #{productTypeCode}

mapper.select:
SELECT f.ID, f.FACTORY_CODE, f.YEAR, f.MONTH, f.PRODUCTION_VERSION, f.MATERIAL_CODE, f.MATERIAL_DESC, f.PRODUCT_STATUS, f.PRODUCT_TYPE_CODE, f.BRAND, f.SPECIFICATIONS, f.PRO_SIZE, f.ORIGINAL_TOTAL_QTY, f.TOTAL_QTY, f.DAY_1, f.DAY_2, f.DAY_3, f.DAY_4, f.DAY_5, f.DAY_6, f.DAY_7, f.DAY_8, f.DAY_9, f.DAY_10, f.DAY_11, f.DAY_12, f.DAY_13, f.DAY_14, f.DAY_15, f.DAY_16, f.DAY_17, f.DAY_18, f.DAY_19, f.DAY_20, f.DAY_21, f.DAY_22, f.DAY_23, f.DAY_24, f.DAY_25, f.DAY_26, f.DAY_27, f.DAY_28, f.DAY_29, f.DAY_30, f.DAY_31 FROM T_MP_MONTH_PLAN_PROD_FINAL f
ORDER BY f.MATERIAL_CODE
LIMIT #{offset}, #{pageSize}

SELECT
    q.MATERIAL_CODE   AS materialCode,
    q.LH_TYPE         AS lhType,
    DAY(q.FINISH_DATE) AS dayNum,
    SUM(q.DAY_FINISH_QTY) AS finishQty
FROM T_LH_DAY_FINISH_QTY q
INNER JOIN T_MP_PROC_VERSION v
    ON v.IS_FINAL = '1'
    AND v.IS_DELETE = 0
    AND v.FACTORY_CODE = #{queryDto.factoryCode}
    AND v.YEAR = #{queryDto.year}
    AND v.MONTH = #{queryDto.month}
WHERE q.IS_DELETE = 0
  AND q.FACTORY_CODE = #{queryDto.factoryCode}
  AND q.FINISH_DATE BETWEEN v.PRODUCTION_START_DATE AND v.PRODUCTION_END_DATE
  AND YEAR(q.FINISH_DATE) = #{queryDto.year}
  AND MONTH(q.FINISH_DATE) = #{queryDto.month}
  AND EXISTS (
      SELECT 1 FROM T_MP_MONTH_PLAN_PROD_FINAL f
      WHERE f.MATERIAL_CODE = q.MATERIAL_CODE
        AND f.PRODUCT_STATUS = q.LH_TYPE
        AND f.PRODUCTION_VERSION = v.PRODUCTION_VERSION
        AND f.FACTORY_CODE = #{queryDto.factoryCode}
        AND f.IS_DELETE = 0
  )

    AND (
        q.MATERIAL_CODE + '|' + q.LH_TYPE
    ) IN

        #{mk}


GROUP BY q.MATERIAL_CODE, q.LH_TYPE, DAY(q.FINISH_DATE)
